package com.findworks.platform;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;public final class Ids{private static final SecureRandom R=new SecureRandom();private Ids(){}public static UUID id(){return UUID.randomUUID();}public static String token(){var b=new byte[32];R.nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}public static String sha(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}public static String challenge(String s){try{return Base64.getUrlEncoder().withoutPadding().encodeToString(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.US_ASCII)));}catch(Exception e){throw new IllegalStateException(e);}}}
